import java.util.*;

class Solution {
    public int minSprinklers(int n, int[] reach) {
        int[] best = new int[n + 1];               // best[l] = farthest right end starting at l
        for (int i = 0; i <= n; i++) {
            int l = Math.max(0, i - reach[i]);
            int r = Math.min(n, i + reach[i]);
            best[l] = Math.max(best[l], r);
        }
        int count = 0, wateredEnd = 0, farthest = 0;
        for (int i = 0; i < n; i++) {
            farthest = Math.max(farthest, best[i]);
            if (i == wateredEnd) {                 // must switch on another sprinkler
                if (farthest <= i) return -1;      // nothing pushes past this point
                count++;
                wateredEnd = farthest;
            }
        }
        return count;
    }
}

