class Solution:
    def minSprinklers(self, n: int, reach: List[int]) -> int:
        best = [0] * (n + 1)
        for i, r in enumerate(reach):
            l = max(0, i - r)
            best[l] = max(best[l], min(n, i + r))
        cnt, end, far = 0, 0, 0
        for i in range(n):
            far = max(far, best[i])
            if i == end:
                if far <= i: return -1
                cnt += 1; end = far
        return cnt

