function minSprinklers(n, reach) {
  const best = new Array(n + 1).fill(0);
  for (let i = 0; i <= n; i++) { const l = Math.max(0, i - reach[i]); best[l] = Math.max(best[l], Math.min(n, i + reach[i])); }
  let cnt = 0, end = 0, far = 0;
  for (let i = 0; i < n; i++) {
    far = Math.max(far, best[i]);
    if (i === end) { if (far <= i) return -1; cnt++; end = far; }
  }
  return cnt;
}
